    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof connectWallet>>, TError,{data: BodyType<WalletConnectInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof connectWallet>>, TError,{data: BodyType<WalletConnectInput>}, TContext> => {

const mutationKey = ['connectWallet'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof connectWallet>>, {data: BodyType<WalletConnectInput>}> = (props) => {
          const {data} = props ?? {};

          return  connectWallet(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ConnectWalletMutationResult = NonNullable<Awaited<ReturnType<typeof connectWallet>>>
    export type ConnectWalletMutationBody = BodyType<WalletConnectInput>
    export type ConnectWalletMutationError = ErrorType<unknown>

    /**
 * @summary Connect wallet and create/return user session
 */
export const useConnectWallet = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof connectWallet>>, TError,{data: BodyType<WalletConnectInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof connectWallet>>,
        TError,
        {data: BodyType<WalletConnectInput>},
        TContext
      > => {
      return useMutation(getConnectWalletMutationOptions(options));
    }

